// ═══════════════════════════════════════════════════════════════════════════
// video_vars.js — n8n Code-узел «Vars» конвейера видео шота (Mode: Run Once for All Items)
//
// Видео шота = кадр раскадровки (первый кадр) + движение + звук; MiniMax H3 i2v.
// Голос #talk-шота — на выбор, по шоту:
//   • у шота есть audio_file (озвучка Google, голос из карточки персонажа) → процесс video-i2v-voice.json:
//     дорожка подаётся в H3 (PixaromaH3AudioSync), видео подстраивает губы; длина — по озвучке;
//   • озвучки нет → процесс video-i2v.json: реплику голосом и губы H3 делает сам, шумы тоже.
// Рассказчик (Narrator) в видео не звучит — его голос накладывается при монтаже.
//
// Выход (для fill_workflow.js и узлов ниже):
//   prompt          — промпт видео (→ #prompt)
//   '#image.image'  — кадр в папке input ComfyUI видео-сервера (тот же относительный путь, что base_image_url)
//   '#size.length'  — длина в кадрах 24 fps (H3: 5 + 17k; 124 ≈ 5.2 с … 362 ≈ 15 с)
//   output_prefix   — anima/<сезон>/<серия>/<NN>-<шот> (#save на видео-сервере)
//   frame_dir, frame_file — кадр: взять из своего ComfyUI (/view, output) и загрузить на видео-сервер (input, тот же путь)
//   has_track, audio_dir, audio_name, '#audio.audio' — дорожка голоса (только у #talk с audio_file), так же, как кадр
//   comfy_url       — ComfyUI видео-сервера; local_comfy_url — свой ComfyUI (.99): из него берём файлы, в него кладём mp4
//   scene_id, seconds, workflow_file
// Узлы: SCENE_NODE, TOPIC_NODE, SEASON_NODE, CHARACTERS_NODE (Supabase).
// ═══════════════════════════════════════════════════════════════════════════

const SCENE_NODE = 'Scene'
const TOPIC_NODE = 'Topic'
const SEASON_NODE = 'Season'
const CHARACTERS_NODE = 'Characters'

// ── Настройки ──────────────────────────────────────────────────────────────
const COMFY_URL = 'http://127.0.0.1:8189'       // Таиланд, RTX 3080 20 GB (туннель thai-tunnel в pm2 на .99)
const LOCAL_COMFY_URL = 'http://127.0.0.1:8188' // свой ComfyUI: /upload/image?type=output пишет mp4 в output .99
const NARRATOR = 'NARRATOR'                     // тег рассказчика (после norm): его текст не озвучивается в видео
const FPS = 24
const MIN_FRAMES = 124                          // ≈ 5.2 с — нижняя граница обученного диапазона H3
const MAX_FRAMES = 362                          // ≈ 15 с
const WORDS_PER_SEC = 2.4                       // темп реплики
const STYLE_LINE = 'Keep the exact art style, colors, characters and composition of the first frame.'
// ───────────────────────────────────────────────────────────────────────────

const norm = (v) => String(v ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '')
const clean = (s) => String(s ?? '').replace(/\s+/g, ' ').trim()
const words = (s) => clean(s).split(' ').filter(Boolean).length
const toFrames = (sec) => {
  const raw = Math.max(5, Math.round(sec * FPS))
  const valid = raw + ((17 - ((raw - 5) % 17)) % 17) // вверх до 5 + 17k
  return Math.min(MAX_FRAMES, Math.max(MIN_FRAMES, valid))
}
const isCyrillic = (s) => /[А-Яа-яЁё]/.test(s)

try {
  const scene = $(SCENE_NODE).first().json
  if (!scene?.scene_id) throw new Error(`Нет шота в узле «${SCENE_NODE}»`)
  const topic = $(TOPIC_NODE).first().json
  const season = $(SEASON_NODE).first().json ?? {}

  const frame = clean(scene.base_image_url).replace(/\\/g, '/').replace(/^\/+/, '')
  if (!frame) throw new Error('У шота нет кадра (base_image_url) — сначала сгенерируйте фото')
  if (/^https?:/i.test(frame)) throw new Error('base_image_url — полный URL; нужен путь относительно ComfyUI/output')
  const motion = clean(scene.action_prompt || scene.action)
  if (!motion) throw new Error('У шота нет описания движения (action_prompt) — сначала Постановщик')

  // Персонажи сезона: кто говорит (для описания голоса)
  const byName = new Map()
  try {
    for (const { json: c } of $(CHARACTERS_NODE).all()) if (c?.name) byName.set(norm(c.name), c)
  } catch {
    /* без узла персонажей — голос описываем только по реплике */
  }

  const speakerTag = clean(scene.speaking_character)
  const line = clean(scene.dialogue_text)
  const isNarrator = norm(speakerTag) === NARRATOR
  const talks = !!line && !!speakerTag && !isNarrator && scene.shot_type === 'talk'
  const track = talks ? clean(scene.audio_file).replace(/\\/g, '/').replace(/^\/+/, '') : ''
  const has_track = !!track

  // ── Звук ──
  let sound
  if (has_track) {
    // Звук задан дорожкой — описываем только губы
    sound = `${speakerTag} speaks, lips moving precisely in sync with the voice track.`
  } else if (talks) {
    const c = byName.get(norm(speakerTag))
    const who = clean(String(c?.text_prompt ?? '').split(',').slice(0, 2).join(','))
    const tone = clean(scene.dialogue_direction || scene.speaker_voice_tone)
    const lang = isCyrillic(line) ? 'Russian' : 'English'
    sound =
      `${speakerTag}${who ? ` (${who})` : ''} speaks${tone ? ` in a ${tone} voice` : ''}, in ${lang}, lips moving in sync: "${line}" ` +
      `Sound: only the speaker's voice and quiet ambience${scene.noice ? ` (${clean(scene.noice)})` : ''}, no music.`
  } else {
    sound = `Nobody speaks, mouths stay closed. Sound: natural ambience${scene.noice ? ` — ${clean(scene.noice)}` : ''}, no speech, no music.`
  }

  // ── Длина: по дорожке голоса; иначе реплика или текст рассказчика должны поместиться ──
  let seconds = Number(scene.audio_duration) || Number(scene.time) || 4
  if (line && !has_track) seconds = Math.max(seconds, words(line) / WORDS_PER_SEC + (talks ? 1.2 : 0.6))
  const length = toFrames(seconds)

  const prompt = [STYLE_LINE, motion, sound].join(' ')

  const dir = `anima/${season.folder || topic.season_id}/${topic.folder || topic.topic_id}`
  const output_prefix = `${dir}/${String(scene.scena ?? 0).padStart(2, '0')}-${scene.shot_num ?? 1}`
  const frame_file = frame.split('/').pop()
  const frame_dir = frame.split('/').slice(0, -1).join('/')

  return [
    {
      json: {
        scene_id: scene.scene_id,
        prompt,
        output_prefix,
        output_dir: dir, // куда положить mp4 на .99 (output/<dir>)
        started_at: Date.now(), // video_result.js сдаётся через TIMEOUT_MIN
        seconds: Math.round((length / FPS) * 10) / 10,
        frame_dir,
        frame_file,
        '#image.image': frame, // на видео-сервере кадр загружается в input/<frame_dir>/<frame_file>
        '#size.length': length,
        has_track,
        audio_dir: track.split('/').slice(0, -1).join('/'),
        audio_name: track.split('/').pop(),
        ...(has_track ? { '#audio.audio': track } : {}), // так же: input/<audio_dir>/<audio_name> на видео-сервере
        comfy_url: COMFY_URL,
        local_comfy_url: LOCAL_COMFY_URL,
        workflow_file: has_track ? 'video-i2v-voice.json' : 'video-i2v.json',
      },
    },
  ]
} catch (error) {
  return [{ json: { error: error.message } }]
}

// ═══════════════════════════════════════════════════════════════════════════
// fill_workflow.js — n8n Code-узел (Mode: Run Once for All Items). ОДИН на все процессы ComfyUI.
//
// Собирает процесс для POST <ComfyUI>/prompt из трёх частей:
//   1. Шаблон — workflows/<файл> (узел WORKFLOW_NODE: HTTP GET http://<админка>/compute/workflows/<файл>).
//   2. Настройки процесса — строка public.process_settings (узел SETTINGS_NODE; страница «Процессы» админки):
//        values: { "#size.width": 768, "#lora.strength_model": 0.42, "#seed.steps": 16, … } — постоянные значения
//        prompt: "mhbh style, {{prompt}}, {{style}}" — шаблон промпта (пусто — просто {{prompt}})
//   3. Переменные запуска — узел VARS_NODE (в каждом конвейере назовите его «Vars»; для кадра — n8n/frame_vars.js):
//        prompt, refs[], output_prefix, style, seed?, …  а также любые «#метка.поле»: значение — подставятся как есть.
//
// По меткам (заголовок узла в ComfyUI, первое слово) заполняется само:
//   #prompt  ← шаблон промпта с {{переменными}}
//   #ref1..N ← refs[0..N-1]; лишние #ref удаляются вместе со входом, который на них ссылается
//            (так же для любого списка: переменная «xs» → узлы #x1..#xN)
//   #save    ← output_prefix
//   #seed    ← seed или случайный
// Скрипт ничего не знает о кадрах, видео или стилях — это задача узла переменных.
// Выход: { comfy_body: { prompt: <процесс> }, save_node, output_prefix, prompt_text, …переменные без списков }
// ═══════════════════════════════════════════════════════════════════════════

// Цепочка последовательная: Vars → Workflow → Process settings → Fill workflow; данные берутся по именам узлов.
// Имена одинаковые во всех конвейерах — скрипт копируется без правок.
const VARS_NODE = 'Vars'                  // переменные запуска (frame_vars.js и т.п.)
const WORKFLOW_NODE = 'Workflow'          // шаблон процесса
const SETTINGS_NODES = ['Process settings', 'process_settings'] // Supabase: process_settings по имени файла (Settings → Always Output Data: вкл.)

const TEXT_FIELDS = ['text', 'prompt', 'value', 'string']
const labelOf = (node) => String(node?._meta?.title ?? '').trim().split(/\s/)[0].toLowerCase()
const render = (tpl, vars) =>
  String(tpl)
    .replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, k) => (vars[k] == null ? '' : Array.isArray(vars[k]) ? vars[k].join(', ') : String(vars[k])))
    .replace(/\s*,\s*(,\s*)+/g, ', ') // пустые переменные не оставляют «, ,»
    .replace(/^\s*,\s*|\s*,\s*$/g, '')
    .trim()

try {
  let vars
  try {
    vars = { ...$(VARS_NODE).first().json }
  } catch {
    throw new Error(`Нет узла «${VARS_NODE}» с переменными запуска — назовите так узел frame_vars.js`)
  }
  if (vars.error) throw new Error(`${VARS_NODE}: ${vars.error}`)

  // 1. Шаблон: HTTP отдаёт его как json; «Extract from File» — в поле data (объектом или строкой)
  const raw = $(WORKFLOW_NODE).first().json
  const src = raw.data !== undefined && !Object.values(raw).some((n) => n && n.class_type) ? raw.data : raw
  const wf = JSON.parse(JSON.stringify(typeof src === 'string' ? JSON.parse(src) : src))
  if (!Object.values(wf).some((n) => n && n.class_type)) throw new Error(`В узле «${WORKFLOW_NODE}» не процесс ComfyUI в API-формате`)

  const byLabel = (label) => Object.entries(wf).filter(([, n]) => labelOf(n) === label)
  const one = (label) => {
    const found = byLabel(label)
    if (found.length > 1) throw new Error(`Метка ${label} стоит на нескольких узлах`)
    return found[0] ?? null
  }
  const setField = (key, value) => {
    const [label, field] = key.split('.')
    const node = one(label.toLowerCase())
    if (!node) return // метки нет в этом процессе — настройка не про него
    if (!field) throw new Error(`«${key}»: нужно «#метка.поле»`)
    node[1].inputs[field] = value
  }

  // 2. Настройки процесса: строки может не быть (тогда — по шаблону), но узел должен быть — иначе это ошибка сборки
  let settings = {}
  let settingsNode = null
  for (const name of SETTINGS_NODES) {
    try {
      const row = $(name).first().json
      settingsNode = name
      // Пустой ответ (строки нет или база не ответила — Always Output Data пропускает его дальше) — не генерируем молча без стиля
      if (!row || !('settings' in row))
        throw new Error(
          `Узел «${name}» вернул пусто: в process_settings нет строки для этого процесса или база не ответила. ` +
            `Создайте настройки в админке (Настройки → Процессы → «Сохранить») и на сервере читайте их узлом Supabase, не Postgres`,
        )
      settings = typeof row.settings === 'string' ? JSON.parse(row.settings) : (row.settings ?? {})
      break
    } catch (e) {
      if (String(e?.message ?? e).includes('вернул пусто')) throw e
      /* узла с таким именем нет — пробуем следующее */
    }
  }
  if (!settingsNode) throw new Error(`Нет узла настроек процесса — назовите узел Supabase с таблицей process_settings одним из: ${SETTINGS_NODES.join(', ')}`)
  for (const [k, v] of Object.entries(settings.values ?? {})) setField(k, v)

  // 3. Переменные «#метка.поле» — как есть
  for (const [k, v] of Object.entries(vars)) if (k.startsWith('#')) setField(k, v)

  // Списки: переменная «refs» → узлы #ref1..#refN; лишние удаляем вместе со входами
  const prefixes = new Set(Object.values(wf).map(labelOf).map((l) => /^#([a-z_]+)\d+$/.exec(l)?.[1]).filter(Boolean))
  for (const p of prefixes) {
    const list = vars[`${p}s`] ?? vars[p]
    if (list != null && !Array.isArray(list)) throw new Error(`Переменная ${p}s должна быть списком`)
    const items = list ?? []
    const nodes = Object.entries(wf).filter(([, n]) => new RegExp(`^#${p}\\d+$`).test(labelOf(n)))
    if (items.length > nodes.length) throw new Error(`${p}s: значений ${items.length}, а узлов #${p}N в процессе ${nodes.length}`)
    for (const [id, node] of nodes) {
      const i = +labelOf(node).slice(p.length + 1)
      if (i <= items.length) {
        const field = 'image' in node.inputs ? 'image' : Object.keys(node.inputs).find((f) => !Array.isArray(node.inputs[f]))
        node.inputs[field] = items[i - 1]
      } else {
        delete wf[id]
        for (const n of Object.values(wf)) for (const [k, v] of Object.entries(n.inputs ?? {})) if (Array.isArray(v) && v[0] === id) delete n.inputs[k]
      }
    }
  }

  // #prompt
  let promptText = null
  const pn = one('#prompt')
  if (pn) {
    if (!String(vars.prompt ?? '').trim()) throw new Error('Пустой prompt в переменных')
    promptText = render(settings.prompt?.trim() || '{{prompt}}', vars)
    pn[1].inputs[TEXT_FIELDS.find((f) => f in pn[1].inputs) ?? 'text'] = promptText
  }

  // #save
  const save = one('#save')
  if (save) {
    if (!vars.output_prefix) throw new Error('Нет output_prefix в переменных')
    save[1].inputs.filename_prefix = vars.output_prefix
  }

  // #seed
  const seed = one('#seed')
  if (seed) seed[1].inputs['noise_seed' in seed[1].inputs ? 'noise_seed' : 'seed'] = vars.seed ?? Math.floor(Math.random() * 2 ** 48)

  const plain = Object.fromEntries(Object.entries(vars).filter(([k, v]) => !Array.isArray(v) && !k.startsWith('#')))
  return [{ json: { ...plain, comfy_body: { prompt: wf }, save_node: save?.[0] ?? null, prompt_text: promptText, prompt_template: settings.prompt?.trim() || '{{prompt}}', settings_node: settingsNode } }]
} catch (error) {
  return [{ json: { error: error.message } }]
}

// ═══════════════════════════════════════════════════════════════════════════
// video_result.js — n8n Code-узел «Result» конвейера видео (Mode: Run Once for All Items)
//
// Разбирает ответ ComfyUI GET /history/<prompt_id> видео-сервера: нашёл ли #save (VHS_VideoCombine) готовый mp4.
// Вход:  $input.first().json — ответ /history/<prompt_id>
//        узлы FILL_NODE (save_node, scene_id) и PROMPT_NODE (prompt_id)
// Выход: { done: false } — ещё считается (n8n ждёт и спрашивает снова);
//        { done: true, ok: true, scene_id, filename, subfolder } — файл на видео-сервере (скачать через /view);
//        { done: true, ok: false, scene_id, error }
// ═══════════════════════════════════════════════════════════════════════════

const FILL_NODE = 'Fill workflow'
const PROMPT_NODE = 'Comfy prompt'
const VARS_NODE = 'Vars'
const TIMEOUT_MIN = 60 // видео-сервер мог получить очередь из многих шотов

let scene_id = null
try {
  const fill = $(FILL_NODE).first().json
  scene_id = fill.scene_id
  if (fill.error) return [{ json: { done: true, ok: false, scene_id, error: fill.error } }]
  const promptId = $(PROMPT_NODE).first().json.prompt_id
  if (!promptId) return [{ json: { done: true, ok: false, scene_id, error: 'ComfyUI не принял процесс (нет prompt_id)' } }]

  const entry = $input.first().json[promptId]
  const startedAt = $(VARS_NODE).first().json.started_at ?? Date.now()
  if (!entry?.status?.completed && Date.now() - startedAt > TIMEOUT_MIN * 60_000)
    return [{ json: { done: true, ok: false, scene_id, error: `Видео не готово за ${TIMEOUT_MIN} мин (prompt_id ${promptId})` } }]
  if (!entry) return [{ json: { done: false, scene_id } }] // в очереди или считается

  const status = entry.status ?? {}
  if (status.status_str === 'error') {
    const err = (status.messages ?? []).find((m) => m[0] === 'execution_error')?.[1] ?? {}
    return [{ json: { done: true, ok: false, scene_id, error: `ComfyUI: ${err.node_type ?? ''} ${err.exception_message ?? 'ошибка выполнения'}`.trim() } }]
  }
  if (!status.completed) return [{ json: { done: false, scene_id } }]

  const out = entry.outputs?.[fill.save_node] ?? {}
  const files = [...(out.gifs ?? []), ...(out.videos ?? []), ...(out.images ?? [])].filter((f) => /\.(mp4|webm|mov)$/i.test(f.filename ?? ''))
  // VHS с аудио сохраняет и немой файл, и «-audio» — берём со звуком
  const file = files.find((f) => /-audio\.\w+$/i.test(f.filename)) ?? files[0]
  if (!file) return [{ json: { done: true, ok: false, scene_id, error: 'Нет видео в выходе узла #save' } }]
  return [{ json: { done: true, ok: true, scene_id, filename: file.filename, subfolder: String(file.subfolder ?? '').replace(/\\/g, '/') } }]
} catch (error) {
  return [{ json: { done: true, ok: false, scene_id, error: error.message } }]
}
